window.ROLES={"checkin":{"label":"Check-in · Quầy vé","emoji":"🎫","scenarios":[{"k":"r_ci_heavy","l":"Hành lý quá cân","s":"You are a passenger at the check-in counter. Your suitcase is five kilos over your allowance. Ask what you can do, complain a little about the fee, then decide."},{"k":"r_ci_visa","l":"Thiếu giấy tờ","s":"You are a passenger flying abroad, but you can't find your visa on your phone. Ask me what you can do and whether you can still check in."},{"k":"r_ci_family","l":"Gia đình muốn ngồi cạnh nhau","s":"You are a parent travelling with two young children, and your seats are not together. Ask me to seat your family together and ask about priority boarding."},{"k":"r_ci_late","l":"Đến quầy muộn","s":"You are a passenger who arrives at the check-in counter 40 minutes before departure, and the counter is closing. Ask me to help you get on the flight."}],"dialogues":[{"them":"Hi, I'd like to check in for the flight to Seoul.","opts":[{"t":"Of course. May I see your passport, please? Are you checking in any bags today?","good":true,"fb":"Nhận khách + xin hộ chiếu + hỏi hành lý."},{"t":"Passport.","good":false,"fb":"Một từ, như ra lệnh; nên nói 'May I see your passport, please?'"},{"t":"Yes, Seoul. You have ticket?","good":false,"fb":"Thiếu 'Do' và 'a'; lại không cần vé in — hộ chiếu là đủ."}]},{"them":"How many carry-on bags can I take?","opts":[{"t":"Two bag no.","good":false,"fb":"Nói kiểu từng chữ, thiếu 's'; khách không hiểu được bao nhiêu."},{"t":"Let me check your ticket. You can take one carry-on bag and one small personal item, like a handbag.","good":true,"fb":"Kiểm tra theo vé của khách + ví dụ cụ thể."},{"t":"Take as many as you like.","good":false,"fb":"Sai — hạn mức tuỳ vé; khách có thể bị chặn ở cửa."}]},{"them":"My name is spelled wrong on the ticket.","opts":[{"t":"Name wrong, cannot fly.","good":false,"fb":"Kết luận vội, thiếu động từ, làm khách hoảng."},{"t":"No problem, nobody checks.","good":false,"fb":"Sai và thiếu trách nhiệm — tên phải khớp giấy tờ."},{"t":"Let me check. It's only one letter, so I'll ask my supervisor if we can correct it here.","good":true,"fb":"Kiểm tra + hỏi cấp trên, không tự quyết."}]},{"them":"Can I pay the excess baggage fee by card?","opts":[{"t":"Yes, you can pay by card or in cash at the ticket desk. It's just next to counter 20.","good":true,"fb":"Trả lời + nơi thanh toán cụ thể."},{"t":"Yes, card can.","good":false,"fb":"Sai trật tự từ: 'Yes, you can pay by card.'"},{"t":"Only cash. Go to the ATM.","good":false,"fb":"Khẳng định khi chưa chắc và nghe cộc."}]},{"them":"I'm a frequent flyer member. Can I use the lounge?","opts":[{"t":"Lounge is for business class only.","good":false,"fb":"Trả lời khi chưa kiểm tra quyền lợi của khách."},{"t":"Let me check your membership level... Yes, you can. The lounge is on the third floor, after passport control.","good":true,"fb":"Kiểm tra hạng thẻ + vị trí phòng chờ."},{"t":"Yes, you go lounge.","good":false,"fb":"Thiếu 'can' và 'to the': 'Yes, you can go to the lounge.'"}]},{"them":"Is the flight on time?","opts":[{"t":"On time, I think.","good":false,"fb":"Không chắc chắn; nên kiểm tra và báo thông tin cụ thể."},{"t":"Yes, time is OK.","good":false,"fb":"Dịch từng chữ 'giờ ổn'; nên nói 'It's on time.'"},{"t":"Yes, it's on time at the moment. Boarding starts at 2:15 at Gate 11.","good":true,"fb":"Trạng thái + giờ lên máy bay + cửa."}]}]},"gate":{"label":"Cửa ra máy bay","emoji":"🛫","scenarios":[{"k":"r_gt_late","l":"Khách đến khi cửa đã đóng","s":"You are a passenger who arrives at the gate two minutes after it closed. You are upset because you have an important meeting. Ask me to let you board."},{"k":"r_gt_bag","l":"Hành lý xách tay quá lớn","s":"You are a passenger at the gate with a big carry-on bag. I tell you it must go in the hold. Ask why, and ask about the laptop inside."},{"k":"r_gt_delay","l":"Hỏi thông tin chậm chuyến","s":"You are a passenger waiting at the gate. The flight is delayed and there is no information. Ask me why, how long, and whether you will miss your connection."},{"k":"r_gt_volunteer","l":"Khách tình nguyện đổi chuyến","s":"The flight is overbooked and you are thinking about taking a later flight. Ask me when the next flight is and what the airline will offer you."}],"dialogues":[{"them":"Can I board now? I'm in row 35.","opts":[{"t":"Row 35 go.","good":false,"fb":"Thiếu động từ đúng: 'Row 35 can board now.'"},{"t":"Yes, rows 30 to 45 are boarding now. May I see your boarding pass and passport, please?","good":true,"fb":"Xác nhận nhóm đang lên + xin giấy tờ."},{"t":"Wait, wait.","good":false,"fb":"Cộc, không giải thích — mà hàng 35 đang được mời lên."}]},{"them":"I'm on standby. Is there a seat for me?","opts":[{"t":"Maybe. You wait and see.","good":false,"fb":"Mơ hồ; nên kiểm tra và báo khi nào có kết quả."},{"t":"Standby no seat.","good":false,"fb":"Thiếu động từ; dù hết ghế cũng cần xin lỗi và nói phương án."},{"t":"Let me check. Yes, we have one seat left. Here is your new boarding pass, seat 41B.","good":true,"fb":"Kiểm tra + báo kết quả + đưa thẻ lên máy bay mới."}]},{"them":"Where can I charge my phone?","opts":[{"t":"There are charging points under the seats by the window, next to Gate 8.","good":true,"fb":"Chỉ chỗ cụ thể."},{"t":"Charge at home.","good":false,"fb":"Vô lý và thiếu lịch sự."},{"t":"I don't know. You find it.","good":false,"fb":"Đẩy việc cho khách."}]},{"them":"Do I have time to buy a coffee?","opts":[{"t":"Coffee is on the plane.","good":false,"fb":"Không trả lời khách có kịp hay không."},{"t":"Yes, boarding starts in 25 minutes. There's a café just behind you, but please be back by 3:10.","good":true,"fb":"Thời gian còn lại + chỗ mua + giờ phải quay lại."},{"t":"No time, never.","good":false,"fb":"Sai và cộc; còn 25 phút là đủ."}]},{"them":"Which boarding group am I in?","opts":[{"t":"Group three, you see.","good":false,"fb":"Cụt lủn, 'you see' không tự nhiên ở đây."},{"t":"You are in group, wait.","good":false,"fb":"Thiếu số nhóm và mạo từ — khách vẫn không biết."},{"t":"You're in group 3. We'll call your group in about ten minutes.","good":true,"fb":"Nói nhóm + khi nào được gọi."}]},{"them":"The flight is delayed. Will I miss my connection in Tokyo?","opts":[{"t":"Let me check your booking. You'll still have 50 minutes in Tokyo. I'll inform the transfer team, and if you miss it, we'll rebook you.","good":true,"fb":"Kiểm tra + thời gian nối còn lại + phương án dự phòng."},{"t":"Maybe miss, sorry.","good":false,"fb":"Thiếu chủ ngữ và 'will', không có phương án."},{"t":"Tokyo is not my problem.","good":false,"fb":"Đẩy trách nhiệm, rất thiếu chuyên nghiệp."}]}]},"cabin":{"label":"Tiếp viên","emoji":"💺","scenarios":[{"k":"r_cb_seat","l":"Khách ngồi nhầm ghế","s":"You are a passenger sitting in the wrong seat on the plane. You don't want to move because you like the window. Talk to me, the flight attendant."},{"k":"r_cb_meal","l":"Phục vụ suất ăn","s":"You are a passenger during meal service. The meal you want is finished, and you have a food allergy. Ask me about other choices."},{"k":"r_cb_sick","l":"Khách không khoẻ","s":"You are a passenger who feels sick and dizzy during the flight. Tell me how you feel and ask for help."},{"k":"r_cb_noise","l":"Khách phàn nàn người bên cạnh","s":"You are a passenger who can't sleep because the passenger next to you is very loud. Ask me to help you or to change your seat."}],"dialogues":[{"them":"Excuse me, I think someone is in my seat.","opts":[{"t":"You sit other seat, same same.","good":false,"fb":"Thiếu 'in another', 'same same' là kiểu nói bồi; nên giúp khách về đúng ghế."},{"t":"Your problem, you tell him.","good":false,"fb":"Đẩy việc cho khách, dễ gây cãi nhau."},{"t":"Let me check your boarding pass. Yes, 18C is your seat. I'll speak to the passenger for you.","good":true,"fb":"Kiểm tra + xác nhận + tiếp viên tự nói chuyện với khách kia."}]},{"them":"Can I have some water, please?","opts":[{"t":"Of course. Would you like it with ice or without?","good":true,"fb":"Đồng ý + hỏi thêm lựa chọn."},{"t":"Water later.","good":false,"fb":"Cụt, không nói khi nào."},{"t":"Yes, water is free.","good":false,"fb":"Không cần nói miễn phí; nên đáp 'Of course' và mang nước."}]},{"them":"I don't feel well. I think I'm going to be sick.","opts":[{"t":"Close your eyes and sleep.","good":false,"fb":"Coi nhẹ tình trạng của khách."},{"t":"I'm sorry to hear that. Here's a sickness bag. Would you like some water? I'll check on you in a few minutes.","good":true,"fb":"Cảm thông + giúp ngay + hẹn quay lại kiểm tra."},{"t":"You eat too much?","good":false,"fb":"Thiếu 'Did', câu hỏi thiếu tế nhị."}]},{"them":"Can I move to the empty row at the back?","opts":[{"t":"OK, go now.","good":false,"fb":"Cho đổi chỗ trước khi cất cánh — ảnh hưởng an toàn và cân bằng tải."},{"t":"No change, never.","good":false,"fb":"Cứng nhắc, không giải thích."},{"t":"Please stay in your seat for take-off. After the seat belt sign goes off, I'll check and let you know.","good":true,"fb":"Giữ an toàn khi cất cánh + hứa kiểm tra sau."}]},{"them":"Is there any vegetarian food left?","opts":[{"t":"I'm sorry, the vegetarian meals are finished. I can bring you bread, salad and some fruit. Would that be OK?","good":true,"fb":"Xin lỗi + phương án thay thế + hỏi ý khách."},{"t":"No vegetarian. You eat chicken.","good":false,"fb":"Ép khách ăn món không phù hợp — rất thiếu tôn trọng."},{"t":"Vegetable finish.","good":false,"fb":"Dịch từng chữ 'hết rau'; 'vegetable' là rau, món chay là 'vegetarian meal'."}]},{"them":"The man next to me is drunk and very loud.","opts":[{"t":"He is happy, it's OK.","good":false,"fb":"Bỏ qua phàn nàn của khách."},{"t":"Thank you for telling me. I'll speak to him now. If you like, I can also find you another seat.","good":true,"fb":"Cảm ơn + xử lý + đưa thêm lựa chọn."},{"t":"You tell him quiet.","good":false,"fb":"Đẩy việc cho khách và sai ngữ pháp ('to be quiet')."}]}]},"baggage":{"label":"Hành lý · Thất lạc","emoji":"🧳","scenarios":[{"k":"r_bg_lost","l":"Hành lý không đến","s":"You are a passenger at the baggage services desk. Your suitcase did not arrive. Describe it and ask when and how you will get it back."},{"k":"r_bg_damage","l":"Vali bị hỏng","s":"You are a passenger whose suitcase arrived with a broken handle and a crack. Complain politely and ask what the airline will do."},{"k":"r_bg_item","l":"Quên đồ trên máy bay","s":"You are a passenger who left a tablet in the seat pocket on the plane. Ask me how to get it back before you leave the airport."},{"k":"r_bg_call","l":"Gọi hỏi tình trạng hành lý","s":"You are a passenger calling baggage services on the second day because your bag has still not arrived. Ask for an update, and be a little frustrated."}],"dialogues":[{"them":"Where is the baggage claim for the flight from Seoul?","opts":[{"t":"It's carousel 5. Go down the stairs, and it's on your right.","good":true,"fb":"Số băng chuyền + chỉ đường."},{"t":"Carousel, you look screen.","good":false,"fb":"Cụt, thiếu 'at the'; nên nói số băng chuyền luôn."},{"t":"Baggage come later.","good":false,"fb":"Sai ngữ pháp ('comes') và không trả lời câu hỏi."}]},{"them":"My bag is the last one missing. Everyone else has theirs.","opts":[{"t":"Maybe somebody take it.","good":false,"fb":"Đoán mò làm khách lo; sai thì ('took')."},{"t":"I'm sorry. Let me check the system with your tag number. If it's not here, I'll help you fill in a report.","good":true,"fb":"Xin lỗi + kiểm tra + bước tiếp theo."},{"t":"Wait one more hour.","good":false,"fb":"Băng chuyền đã hết hành lý — bắt khách chờ vô ích."}]},{"them":"How will you find my bag?","opts":[{"t":"We try, but maybe no.","good":false,"fb":"Thiếu 'will', nghe bi quan, khách mất niềm tin."},{"t":"You call every airport.","good":false,"fb":"Đẩy việc cho khách — đây là việc của hãng."},{"t":"We'll send your bag details to all the airports on your route. The system will look for your tag number.","good":true,"fb":"Giải thích quy trình tìm kiếm rõ ràng."}]},{"them":"Do I have to come back to the airport to pick it up?","opts":[{"t":"No, you don't. We'll deliver it to your hotel or home. Could you write the address here, please?","good":true,"fb":"Trả lời rõ + xin địa chỉ giao."},{"t":"Yes, come airport again.","good":false,"fb":"Thiếu 'to the', cộc; nên kiểm tra và đề nghị giao tận nơi."},{"t":"Up to you.","good":false,"fb":"Không trả lời, khách không biết làm gì."}]},{"them":"My bag was damaged. Who will pay for it?","opts":[{"t":"Airline pay all, no problem.","good":false,"fb":"Hứa bừa thay công ty và sai ngữ pháp ('The airline will pay')."},{"t":"I'm sorry. Let me write a damage report. Our claims team will contact you about a repair or other options.","good":true,"fb":"Xin lỗi + lập biên bản + ai sẽ liên hệ, không hứa bừa."},{"t":"Bags break every day. Normal.","good":false,"fb":"Coi nhẹ thiệt hại của khách."}]},{"them":"This suitcase looks like mine, but it's not! Someone took my bag by mistake.","opts":[{"t":"Take this one. Same colour.","good":false,"fb":"Rất sai — không được đưa hành lý của người khác."},{"t":"Not our problem. Call the police.","good":false,"fb":"Đẩy trách nhiệm; hãng có thể liên hệ khách cầm nhầm."},{"t":"Thank you for telling us. Let me check the name tag on this bag. We'll contact the other passenger and get your bag back.","good":true,"fb":"Cảm ơn + kiểm tra + liên hệ khách cầm nhầm."}]}]}};
